'use strict';
window.OwnerInbox=(()=>{
  let data=null,settings=null,detail=null,selected=0,page=0,screen='inbox',error='',notice='',busy=false,topicId=0,epoch=0;
  const drafts=new Map(),keys=new Map(),forms=new Map();
  const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const labels={new:'Новый',working:'В работе',hot:'Заинтересован',closed:'Закрыт',pending:'В очереди',sending:'Отправляется',sent:'Отправлено',received:'Получено',failed:'Не отправлено',uncertain:'Нужно проверить в Telegram',cancelled:'Отменено'};
  const b=(name,action,id='')=>`<button type="button" class="button secondary" data-o-action="${action}" data-id="${h(id)}">${h(name)}</button>`;
  const field=(name,label,value='',type='text',extra='')=>`<label class="ls-field">${h(label)}<input name="${name}" type="${type}" value="${h(value)}" ${extra}></label>`;
  const area=(name,label,value='',max=8000)=>`<label class="ls-field">${h(label)}<textarea name="${name}" rows="4" maxlength="${max}">${h(value)}</textarea></label>`;
  const check=(name,label,value)=>`<label class="ls-check"><input name="${name}" type="checkbox" ${value?'checked':''}>${h(label)}</label>`;
  const date=v=>v?new Date(v).toLocaleString('ru-RU'):'';
  async function api(path='',body){
    const r=await fetch('/api/scanner/marketing/conversations'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Scanner-Request':'1'},signal:AbortSignal.timeout(45000),...(body===undefined?{}:{body:JSON.stringify(body)})});
    let d;try{d=await r.json();}catch{throw Error('Сервис не ответил. Текст сохранён; повтор загрузки безопасен.');}
    if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'Проверьте заполнение полей.');return d;
  }
  const root=()=>document.querySelector('#owner-conversation-inbox');
  function view(){return '<div id="owner-conversation-inbox"><div class="empty"><strong>Загружаем переписку…</strong></div></div>';}
  async function mount(){await reload();}
  async function reload(){
    const version=++epoch;
    try{
      const [next,cfg]=await Promise.all([api('?offset='+page),api('/settings')]);
      if(version!==epoch)return;data=next;settings=cfg;
      if(selected){const d=await api('/'+selected);if(version!==epoch)return;detail=d;}
      error='';render();
    }catch(e){if(version===epoch){error=e.message;render();}}
  }
  async function open(leadId,{draft}={}){await action(async()=>{detail=await api('/open',{lead_id:leadId});selected=detail.conversation.id;screen='inbox';if(!settings)settings=await api('/settings');data=await api('?offset='+page);if(typeof draft==='string'&&draft.trim())drafts.set(selected,draft.slice(0,4096));else if(!drafts.has(selected))drafts.set(selected,detail.messages.length?'':detail.draft);},false);}
  async function action(fn,refresh=true){if(busy)return;busy=true;error='';notice='';try{await fn();if(refresh)await reload();else render();}catch(e){error=e.message;render();}finally{busy=false;}}
  function formKey(f){return f.dataset.oForm==='topic'?'topic:'+topicId:f.dataset.oForm;}
  function rememberForm(f){if(!f?.matches('[data-o-form="settings"],[data-o-form="topic"]'))return;forms.set(formKey(f),Object.fromEntries([...f.elements].filter(x=>x.name&&x.name!=='api_key').map(x=>[x.name,x.type==='checkbox'?x.checked:x.value])));}
  function restoreForms(){root()?.querySelectorAll('[data-o-form]').forEach(f=>{const values=forms.get(formKey(f));if(values)for(const el of f.elements)if(Object.hasOwn(values,el.name)){if(el.type==='checkbox')el.checked=values[el.name];else el.value=values[el.name];}});}
  function render(){const el=root();if(!el)return;
    el.innerHTML=`<div class="cm-toolbar"><div><h2>Переписка с клиентами</h2><p>${data?`${data.unread} непрочитанных · ${data.total} диалогов`:'Личные сообщения из найденных запросов'}</p></div><div class="ls-actions">${b('Диалоги','inbox')}${b('Настройки ИИ','settings')}${b('Обновить','refresh')}</div></div>${error?`<div class="ls-error" role="alert">${h(error)}</div>`:''}${notice?`<div class="notice" role="status">${h(notice)}</div>`:''}${data?.error?`<div class="ls-error">${h(data.error)}</div>`:''}${settings?`<div class="cm-automation"><span>${settings.config.paused?'Автоматика на паузе':'Автоматика включена'} · ${settings.key_configured?(settings.config.provider_verified?'Claude через Tokenn проверен':'Ключ нужно проверить'):'Ключ ИИ не подключён'}</span>${!settings.config.paused?b('Остановить всю автоматику','pause'):''}</div>`:''}${settings?.provider_error?`<div class="ls-error">${h(settings.provider_error)}</div>`:''}<div class="notice">Личный помощник отвечает только на новые входящие в выбранных деловых диалогах. Первый контакт и повторные предложения отключены. При твоём ручном ответе ИИ останавливается.</div>${screen==='settings'?settingsView():inboxView()}`;restoreForms();
  }
  function inboxView(){if(!data)return b('Повторить загрузку','refresh');return `<div class="cm-layout"><aside class="cm-list" aria-label="Список диалогов">${data.conversations.length?data.conversations.map(c=>`<button type="button" class="cm-contact ${c.id===selected?'selected':''}" data-o-action="select" data-id="${c.id}"><strong>${h(c.title)} ${c.unread?`<span class="badge amber">${c.unread}</span>`:''}</strong><span>${h(c.username?'@'+c.username:'ID '+c.peer_id)}</span><small>${h(labels[c.status])} · ${c.mode==='ai'?'ИИ':'Менеджер'}</small>${c.error?'<small class="ls-error">Требуется внимание</small>':''}</button>`).join(''):'<div class="empty"><strong>Диалогов пока нет</strong>В «Находках» нажмите «Обсудить с автором» у подходящего запроса. Сообщение само не отправится.</div>'}<div class="ls-actions">${page?b('Назад','page',Math.max(0,page-100)):''}${page+100<data.total?b('Далее','page',page+100):''}</div>${data.open_errors.length?`<details><summary>Не удалось начать ${data.open_errors.length} диалогов</summary>${data.open_errors.map(x=>`<p>Лид №${x.lead_id}: ${h(x.error)}</p>`).join('')}</details>`:''}</aside><section class="cm-dialog" aria-label="Личная переписка">${detail?dialogView():'<div class="empty"><strong>Выберите диалог</strong>Здесь будут история, ответы и задача менеджеру.</div>'}</section></div>`;}
  function dialogView(){const c=detail.conversation;const draft=drafts.get(c.id)??'';
    return `<header class="cm-dialog-head"><div><h3>${h(c.title)}</h3><p>Личный получатель: ${h(c.username?'@'+c.username:'без username')} · ID ${c.peer_id}<br>Отправитель: ${h(detail.sender||'Аккаунт не подключён')} · ID ${c.account_id}</p></div><span class="badge ${c.status==='hot'?'green':'amber'}">${h(labels[c.status])}</span></header><details class="cm-origin"><summary>Исходный запрос · ${h(detail.topic)}</summary><p class="ls-message">${h(detail.lead.text)}</p><p>${h(detail.lead.source_title)} · ${h(detail.lead.author)}</p>${/^https:\/\/t\.me\//.test(detail.lead.link||'')?`<a href="${h(detail.lead.link)}" target="_blank" rel="noopener noreferrer">Открыть источник</a>`:''}<p>Связанные лиды: ${detail.linked_leads.map(h).join(', ')}</p></details>${c.error?`<div class="ls-error">${h(c.error)}</div>`:''}${c.stopped?'<div class="notice amber">Собеседник отказался от сообщений. Ручная и автоматическая отправка остановлены.</div>':''}<div class="cm-controls">${b('Взять диалог вручную','takeover')}${b('Отметить прочитанным','read')}${b('Проверить входящие','sync')}<form data-o-form="control"><label>Статус <select name="status">${['new','working','hot','closed'].filter(s=>s!=='hot'||c.status==='hot').map(s=>`<option value="${s}" ${c.status===s?'selected':''}>${h(labels[s])}</option>`).join('')}</select></label><label>Режим <select name="mode"><option value="manual">Менеджер</option><option value="ai" ${c.mode==='ai'?'selected':''} ${!detail.ai_ready||c.stopped?'disabled':''}>ИИ отвечает на входящие</option></select></label><button class="button secondary" data-o-submit>Применить</button></form></div>${Object.keys(c.facts).length?`<details open class="cm-facts"><summary>Что уже известно</summary><dl>${Object.entries(c.facts).map(([k,v])=>`<dt>${h({need:'Потребность',city:'Город',date:'Дата',budget:'Бюджет',details:'Детали',contact:'Связь',contact_time:'Время связи'}[k]||k)}</dt><dd>${h(v.value)}<small>«${h(v.evidence)}»</small></dd>`).join('')}</dl></details>`:''}${c.handoff.created?`<section class="notice cm-handoff"><h3>${c.handoff.hot?'Готов к разговору с менеджером':'Нужен менеджер'}</h3><p class="ls-message">${h(c.handoff.summary)}</p>${c.handoff.hot?`<p>Интерес: «${h(c.handoff.interest_quote)}»<br>Готовность к связи: «${h(c.handoff.contact_quote)}»</p>`:''}<p><strong>Дальше:</strong> ${h(c.handoff.next_action)}</p><p>Не уточнено: ${h(c.handoff.unknown.join(', ')||'нет')}</p><p>ИИ поставлен на паузу.</p></section>`:''}<div class="cm-messages" aria-label="История сообщений">${detail.older_before?b('Загрузить более ранние','older',detail.older_before):''}${detail.messages.length?detail.messages.map(m=>`<article class="cm-message ${m.direction==='outgoing'?'out':'in'}"><div class="cm-message-meta">${m.direction==='incoming'?'Собеседник':m.kind==='ai'?'ИИ-помощник':m.kind==='external'?'Отправлено в Telegram':'Менеджер'} · ${h(date(m.created))}</div><p>${h(m.text)}</p><small>${h(labels[m.state]||m.state)}${m.tg_id?' · Telegram №'+m.tg_id:''}</small>${m.error?`<p class="ls-error">${h(m.error)}</p>`:''}${m.state==='failed'?b('Повторить после проверки','retry',m.id):''}</article>`).join(''):'<p class="muted">Последних сообщений пока нет. Проверьте получателя и отредактируйте первый текст.</p>'}</div><form data-o-form="send" class="cm-compose">${area('text','Сообщение в личный диалог',draft,4096)}<p class="muted small">Ручная отправка ставит ИИ на паузу. В общий чат источника сообщение не отправляется.</p>${check('confirmed',`Отправить от ${detail.sender||'аккаунта'} пользователю ${c.title} (ID ${c.peer_id})`,false)}<button class="button" data-o-submit ${c.stopped||!detail.connected?'disabled':''}>Отправить в личные сообщения</button></form>`;
  }
  function settingsView(){if(!settings)return b('Загрузить настройки','refresh');const s=settings.config;const t=settings.topics.find(x=>x.id===Number(topicId))||settings.topics[0];if(t)topicId=t.id;
    return `<div class="cm-settings"><section class="panel ls-section"><h3>Подключение ИИ и лимиты</h3><p>Claude через Tokenn получает исходный запрос и историю выбранного диалога. Доступ к Telegram, паролям и другим чатам модели не передаётся. Запросы оплачиваются с баланса Tokenn.</p><form data-o-form="settings">${field('api_key',settings.key_configured?'Новый ключ Claude через Tokenn (пусто — сохранить текущий)':'Ключ Claude через Tokenn','','password','autocomplete="off" maxlength="512"')}${check('clear_key','Удалить сохранённый ключ',false)}${field('model','Название модели Claude через Tokenn',s.model,'text','placeholder="Модель из вашего аккаунта API" maxlength="100" required')}${check('consent','Разрешаю передавать тексты выбранных диалогов Claude через Tokenn для квалификации',s.consent)}${check('paused','Общая пауза автоматики',s.paused)}${check('auto_reply','Автоматические ответы на входящие в диалогах с режимом ИИ',s.auto_reply)}<p class="muted small">Автоматический первый контакт отключён для личного аккаунта. ИИ подключается отдельно в каждом просмотренном диалоге и отвечает только на новые входящие.</p>${field('daily_messages','До исходящих сообщений в сутки (включая ручные)',s.daily_messages,'number','min="1" max="20" required')}<p class="small muted">Это предел панели за день UTC. Ограничения Telegram проверяются отдельно; увеличение значения не включает отправку.</p>${field('daily_ai_calls','До запросов ИИ в сутки',s.daily_ai_calls,'number','min="1" max="20" required')}${field('max_ai_replies','До ответов ИИ в одном диалоге',s.max_ai_replies,'number','min="1" max="3" required')}${field('delay_seconds','Пауза для объединения входящих, секунд',s.delay_seconds,'number','min="60" max="3600" required')}<p>Привязка: ${h(settings.account_name||'Telegram не подключён')} · ID ${h(settings.account_id||'—')}</p><button class="button" data-o-submit>Сохранить настройки</button></form><p>${b('Проверить Claude через Tokenn на тестовом примере','provider-test')}</p><p class="muted small">Проверка расходует один запрос API, использует выдуманный пример и ничего не отправляет в Telegram. Пока ключ/модель не проверены, общую паузу снять нельзя.</p><p>Сегодня запросов ИИ: ${settings.usage[0]?.calls||0}; входных токенов: ${settings.usage[0]?.input_tokens||0}; выходных: ${settings.usage[0]?.output_tokens||0}.</p></section><section class="panel ls-section"><h3>Сценарий по тематике</h3><label class="ls-field">Тема<select data-o-topic>${settings.topics.map(x=>`<option value="${x.id}" ${x.id===topicId?'selected':''}>${h(x.name)}</option>`).join('')}</select></label>${t?`<form data-o-form="topic"><label class="ls-field">Режим темы<select name="mode"><option value="manual">Только менеджер</option><option value="ai" ${t.mode==='ai'?'selected':''}>Разрешить ИИ</option></select></label>${field('max_replies','До ответов ИИ по теме в диалоге',t.max_replies,'number','min="1" max="3" required')}${field('company','Название компании или проекта',t.company,'text','maxlength="120"')}${area('facts','Подтверждённые услуги, география, цены и ограничения',t.facts)}${area('questions','Что уточнить у клиента',t.questions,3000)}${area('handoff','Когда передать менеджеру',t.handoff,2000)}${area('first_text','Шаблон для ручного первого сообщения',t.first_text,1500)}<p class="muted small">Подстановки: {company}, {source}, {topic}. Укажите, что пишет помощник. Не обещайте неподтверждённую цену или наличие.</p>${check('reviewed','Я проверил сведения, вопросы и текст первого контакта',t.reviewed)}<button class="button" data-o-submit>Сохранить сценарий</button></form>`:''}<div class="notice">ИИ уточняет запрос, а продажу завершает менеджер. Отказ останавливает сообщения. Интерес и готовность к связи подтверждаются цитатами; обычное «спасибо» не делает лид горячим.</div></section></div>`;
  }
  document.addEventListener('input',e=>{rememberForm(e.target.closest('[data-o-form]'));if(e.target.matches('[data-o-form="send"] textarea'))drafts.set(selected,e.target.value);});
  document.addEventListener('change',e=>{rememberForm(e.target.closest('[data-o-form]'));if(e.target.matches('[data-o-topic]')){topicId=Number(e.target.value);render();}});
  document.addEventListener('click',e=>{const el=e.target.closest('[data-o-action]');if(!el)return;const a=el.dataset.oAction,id=Number(el.dataset.id);
    if(a==='settings'||a==='inbox'){screen=a;render();return;}
    action(async()=>{
      if(a==='select'){selected=id;detail=await api('/'+id);if(!drafts.has(id))drafts.set(id,detail.messages.length?'':detail.draft);}
      if(a==='refresh')return;
      if(a==='page'){page=id;return;}
      if(a==='pause')await api('/settings',{...settings.config,paused:true});
      if(a==='provider-test'){const r=await api('/provider-test',{});notice=r.note;}
      if(a==='takeover')await api('/'+selected+'/control',{mode:'manual',status:detail.conversation.status==='hot'?'hot':'working'});
      if(a==='read')await api('/'+selected+'/read',{through_id:Math.max(0,...detail.messages.map(m=>m.id))});
      if(a==='sync')await api('/'+selected+'/sync',{});
      if(a==='retry'){if(!confirm('Повторить это сообщение тому же личному получателю? Telegram ранее вернул отказ.'))return;await api('/'+selected+'/messages/'+id+'/retry',{confirmed:true});}
      if(a==='older'){const older=await api('/'+selected+'?before='+id);detail.messages=[...older.messages,...detail.messages];detail.older_before=older.older_before;}
    },a!=='older');
  });
  document.addEventListener('submit',e=>{const f=e.target;if(!f.matches('[data-o-form]'))return;e.preventDefault();if(busy)return;rememberForm(f);const savedFormKey=formKey(f);const d=new FormData(f),get=n=>String(d.get(n)||'').trim();f.querySelector('[data-o-submit]').disabled=true;
    action(async()=>{
      if(f.dataset.oForm==='send'){
        if(!d.has('confirmed'))throw Error('Подтвердите личного получателя перед отправкой.');
        if(!keys.has(selected))keys.set(selected,crypto.randomUUID());
        await api('/'+selected+'/send',{text:get('text'),request_key:keys.get(selected),account_id:detail.conversation.account_id,peer_id:detail.conversation.peer_id,confirmed:true});drafts.set(selected,'');keys.delete(selected);notice='Сообщение поставлено в очередь. Результат появится в истории.';
      }
      if(f.dataset.oForm==='control')await api('/'+selected+'/control',{mode:get('mode'),status:get('status')});
      if(f.dataset.oForm==='settings')await api('/settings',{model:get('model'),api_key:get('api_key'),clear_key:d.has('clear_key'),paused:d.has('paused'),auto_reply:d.has('auto_reply'),auto_first:false,consent:d.has('consent'),account_id:settings.account_id,daily_messages:Number(get('daily_messages')),daily_ai_calls:Number(get('daily_ai_calls')),max_ai_replies:Number(get('max_ai_replies')),delay_seconds:Number(get('delay_seconds'))});
      if(f.dataset.oForm==='topic')await api('/topics/'+topicId,{mode:get('mode'),max_replies:Number(get('max_replies')),company:get('company'),facts:get('facts'),questions:get('questions'),handoff:get('handoff'),first_text:get('first_text'),reviewed:d.has('reviewed'),auto_first:false});
      forms.delete(savedFormKey);
    });
  });
  setInterval(()=>{if(document.visibilityState!=='hidden'&&root()&&screen==='inbox'&&!busy&&!root().contains(document.activeElement))reload();},10000);
  return {view,mount,open};
})();
